package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.remote.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage8/remote") public class RemoteCompanionController {private final RemoteCompanionService service;public RemoteCompanionController(RemoteCompanionService service){this.service=service;}public record PairRequest(Set<String> capabilities,int ttlMinutes){}public record AuthRequest(String token,String capability){}@PostMapping("/pair") public RemoteCompanionSessionResponse pair(@RequestBody PairRequest r){return service.pair(r.capabilities(),r.ttlMinutes());}@PostMapping("/{id}/authenticate") public Map<String,Object> auth(@PathVariable UUID id,@RequestBody AuthRequest r){RemoteCompanionSessionEntity e=service.authenticate(id,r.token(),r.capability());return Map.of("authenticated",true,"sessionId",e.getId(),"capabilities",e.capabilities());}@PostMapping("/{id}/revoke") public Map<String,Object> revoke(@PathVariable UUID id){service.revoke(id);return Map.of("revoked",true);}}
